package com.bookeat.payment.service;
import com.bookeat.payment.entity.*;import com.bookeat.payment.enums.*;import com.bookeat.payment.repository.*;import com.bookeat.payment.dto.*;import com.bookeat.payment.gateway.GatewayPort;
import com.bookeat.order.repository.*;import com.bookeat.order.entity.FoodOrder;import com.bookeat.order.enums.*;
import com.bookeat.reservation.repository.*;import com.bookeat.reservation.enums.*;import com.bookeat.dining.repository.DiningSessionRepository;import com.bookeat.dining.enums.DiningStatus;import com.bookeat.diniticket.repository.DiniTicketRepository;
import com.bookeat.commerce.service.*;import com.bookeat.common.audit.AuditService;import com.bookeat.exception.*;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;import java.time.*;import java.math.BigDecimal;
@Service @RequiredArgsConstructor @Transactional
public class PaymentTransactions {
 private final PaymentRepository payments;private final PaymentLineRepository lines;private final FoodOrderRepository orders;private final ReservationRepository reservations;private final GroupBookingRepository groups;private final GroupMemberRepository members;private final CorporateBookingRepository corporate;private final TakeawayOrderRepository takeaways;private final DiniTicketRepository tickets;private final DiningSessionRepository dining;private final CommissionRuleRepository commissions;private final CommerceAccess access;private final IdempotencyService idempotency;private final JdbcTemplate jdbc;private final Clock clock;private final AuditService audit;private final List<PaymentWalletPort> wallets;private final GatewayPort gateway;private final com.bookeat.admin.service.PromotionService promotions;
 public UUID reserve(UUID actor,String key,PaymentRequests.Create q){if(q.gateway()!=PaymentGateway.CASH&&q.gateway()!=PaymentGateway.WALLET&&q.gateway()!=PaymentGateway.RAZORPAY)throw new ApiException(ErrorCode.PAYMENT_INVALID);return idempotency.execute(actor,"payment-create",key,q,()->{UUID c=access.customer(actor);String table=switch(q.referenceType()){case FOOD_ORDER->"food_orders";case TAKEAWAY->"takeaway_orders";case RESERVATION->"reservations";case GROUP_BOOKING->"group_bookings";case CORPORATE_BOOKING->"corporate_bookings";case DINITICKET->"dini_tickets";case DINING_BILL->"dining_sessions";};UUID rid=jdbc.query("select restaurant_id from "+table+" where id=?",(r,n)->r.getObject(1,UUID.class),q.referenceId()).stream().findFirst().orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.lock(rid);var selected=select(c,q);if(selected.isEmpty())throw new ApiException(ErrorCode.PAYMENT_NOT_DUE);if(selected.stream().anyMatch(o->!o.getRestaurantId().equals(rid)))throw new ApiException(ErrorCode.PAYMENT_INVALID);if(q.gateway()==PaymentGateway.RAZORPAY&&!gateway.enabled())throw new ApiException(ErrorCode.PAYMENT_GATEWAY_UNAVAILABLE);if(q.gateway()==PaymentGateway.RAZORPAY&&q.referenceType()==PaymentReferenceType.TAKEAWAY&&!Boolean.TRUE.equals(jdbc.queryForObject("select accept_online_payment from restaurant_takeaway_settings where restaurant_id=?",Boolean.class,rid)))throw new ApiException(ErrorCode.PAYMENT_INVALID);if(q.gateway()==PaymentGateway.CASH&&q.referenceType()==PaymentReferenceType.TAKEAWAY){var cfg=jdbc.queryForObject("select accept_cash from restaurant_takeaway_settings where restaurant_id=?",Boolean.class,rid);if(!Boolean.TRUE.equals(cfg))throw new ApiException(ErrorCode.PAYMENT_INVALID);}
  var remaining=new LinkedHashMap<UUID,BigDecimal>();for(var o:selected){if(o.getStatus()==FoodOrderStatus.CANCELLED||o.getStatus()==FoodOrderStatus.REJECTED)continue;BigDecimal available=o.getTotal().subtract(claimed(o.getId()));if(available.signum()>0)remaining.put(o.getId(),available);}
  BigDecimal total=remaining.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add);if(q.referenceType()==PaymentReferenceType.GROUP_BOOKING){var g=groups.findById(q.referenceId()).orElseThrow();if(g.getPaymentMode()==GroupPaymentMode.SPLIT_EQUAL){var joined=members.findByGroupBookingIdOrderByJoinedAtAscIdAsc(g.getId()).stream().filter(m->m.getMemberStatus()==MemberStatus.JOINED).sorted(Comparator.comparing(m->m.getId())).toList();int index=-1;for(int i=0;i<joined.size();i++)if(joined.get(i).getCustomerId().equals(c))index=i;if(index<0)throw new ApiException(ErrorCode.ACCESS_DENIED);BigDecimal gross=selected.stream().filter(o->o.getStatus()!=FoodOrderStatus.CANCELLED&&o.getStatus()!=FoodOrderStatus.REJECTED).map(FoodOrder::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal share=com.bookeat.order.service.OrderRules.splitEqual(gross,joined.size()).get(index);BigDecimal previous=jdbc.queryForObject("select coalesce(sum(amount),0) from payments where reference_type='GROUP_BOOKING' and reference_id=? and customer_id=? and status<>'FAILED'",BigDecimal.class,g.getId(),c);total=share.subtract(previous).min(total);}}
  if(total.signum()<=0)throw new ApiException(ErrorCode.PAYMENT_NOT_DUE);if(total.compareTo(new BigDecimal("999999999999.99"))>0)throw new ApiException(ErrorCode.PAYMENT_INVALID);var p=new Payment();p.setCustomerId(c);p.setRestaurantId(rid);p.setReferenceType(q.referenceType());p.setReferenceId(q.referenceId());p.setGateway(q.gateway());if(q.gateway()==PaymentGateway.RAZORPAY){p.setGatewayAccountId(gateway.accountId());p.setGatewaySandbox(gateway.sandbox());}p.setAmount(total);p.setDiscountAmount(BigDecimal.ZERO);p.setCurrency("INR");p.setStatus(PaymentStatus.CREATED);p.setRefundedAmount(BigDecimal.ZERO);p.setGatewayFee(BigDecimal.ZERO);p.setGatewayTax(BigDecimal.ZERO);p.setCommissionAmount(BigDecimal.ZERO);String service=selected.get(0).getOrderType()==OrderType.TAKEAWAY||selected.get(0).getOrderType()==OrderType.ON_THE_WAY?"TAKEAWAY":selected.get(0).getOrderType()==OrderType.DINITICKET_PREORDER?"DINITICKET":"RESTAURANT";var rules=commissions.findAll().stream().filter(r->r.isActive()&&r.getServiceType().equals(service)&&!clock.instant().isBefore(r.getEffectiveFrom())&&(r.getEffectiveUntil()==null||clock.instant().isBefore(r.getEffectiveUntil()))).sorted(Comparator.comparing(CommissionRule::getEffectiveFrom).reversed().thenComparing(CommissionRule::getId)).toList();if(!rules.isEmpty()){var rule=rules.get(0);p.setCommissionRuleId(rule.getId());p.setCommissionAmount(PaymentRules.commission(total,rule.getCommissionType()==CommissionType.PERCENTAGE,rule.getCommissionValue()));}payments.saveAndFlush(p);
  BigDecimal coverage=total;if(q.couponCode()!=null){if(q.referenceType()==PaymentReferenceType.GROUP_BOOKING&&groups.findById(q.referenceId()).orElseThrow().getPaymentMode()==GroupPaymentMode.SPLIT_EQUAL)throw new ApiException(ErrorCode.PROMOTION_INVALID);BigDecimal discount=promotions.redeem(q.couponCode(),c,rid,service,total,p.getId());p.setDiscountAmount(discount);total=total.subtract(discount);p.setAmount(total);if(p.getCommissionRuleId()!=null){var rule=commissions.findById(p.getCommissionRuleId()).orElseThrow();p.setCommissionAmount(PaymentRules.commission(total,rule.getCommissionType()==CommissionType.PERCENTAGE,rule.getCommissionValue()));}}
  BigDecimal toAllocate=coverage;for(var e:remaining.entrySet()){if(toAllocate.signum()==0)break;BigDecimal amount=e.getValue().min(toAllocate);var l=new PaymentLine();l.setPaymentId(p.getId());l.setFoodOrderId(e.getKey());l.setAmount(amount);lines.save(l);toAllocate=toAllocate.subtract(amount);}if(toAllocate.signum()!=0)throw new ApiException(ErrorCode.PAYMENT_INVALID);
  if(q.gateway()==PaymentGateway.WALLET){if(wallets.isEmpty())throw new ApiException(ErrorCode.PAYMENT_GATEWAY_UNAVAILABLE);for(var w:wallets)w.debit(c,p.getId(),total,actor);success(p,actor,null,"WALLET",BigDecimal.ZERO,BigDecimal.ZERO);}else if(q.gateway()==PaymentGateway.CASH){p.setStatus(PaymentStatus.PENDING);payments.flush();audit.record(actor,"PAYMENT_CASH_CONFIRMED","Payment",p.getId(),null);}payments.flush();return p.getId();});}
 private List<FoodOrder> select(UUID c,PaymentRequests.Create q){List<FoodOrder> list;switch(q.referenceType()){
 case FOOD_ORDER->{var o=orders.findById(q.referenceId()).filter(x->x.getCustomerId().equals(c)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));if(o.getGroupBookingId()!=null||o.getTakeawayOrderId()!=null)throw new ApiException(ErrorCode.PAYMENT_INVALID);if(o.getCorporateBookingId()!=null&&corporate.findById(o.getCorporateBookingId()).orElseThrow().getBillingType()==BillingType.COMPANY)throw new ApiException(ErrorCode.PAYMENT_INVALID);list=List.of(o);}
 case TAKEAWAY->{var t=takeaways.findById(q.referenceId()).filter(x->x.getCustomerId().equals(c)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));list=List.of(orders.findById(t.getFoodOrderId()).orElseThrow());}
 case RESERVATION->{var r=reservations.findByIdAndCustomerId(q.referenceId(),c).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));if(r.getBookingType()!=BookingType.REGULAR)throw new ApiException(ErrorCode.PAYMENT_INVALID);list=orders.findByReservationId(r.getId());}
 case GROUP_BOOKING->{var g=groups.findById(q.referenceId()).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));if(members.findByGroupBookingIdAndCustomerId(g.getId(),c).filter(m->m.getMemberStatus()==MemberStatus.JOINED).isEmpty())throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);if(g.getPaymentMode()==GroupPaymentMode.HOST_PAYS&&!g.getHostCustomerId().equals(c))throw new ApiException(ErrorCode.ACCESS_DENIED);if(g.getPaymentMode()==GroupPaymentMode.SPLIT_EQUAL&&g.getStatus()!=GroupStatus.LOCKED)throw new ApiException(ErrorCode.PAYMENT_INVALID);list=orders.findByGroupBookingId(g.getId());if(g.getPaymentMode()==GroupPaymentMode.SPLIT_BY_ITEMS)list=list.stream().filter(o->o.getCustomerId().equals(c)).toList();}
 case CORPORATE_BOOKING->{var b=corporate.findById(q.referenceId()).filter(x->x.getOrganizerCustomerId().equals(c)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));list=orders.findByCorporateBookingId(b.getId());}
 case DINITICKET->{var t=tickets.findById(q.referenceId()).filter(x->x.getCustomerId().equals(c)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));list=orders.findByDiniTicketId(t.getId());}
 case DINING_BILL->{var d=dining.findById(q.referenceId()).filter(x->x.getCustomerId().equals(c)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));if(d.getStatus()!=DiningStatus.PAYMENT_PENDING)throw new ApiException(ErrorCode.PAYMENT_NOT_DUE);if(d.getReservationId()!=null){var r=reservations.findById(d.getReservationId()).orElseThrow();if(r.getBookingType()==BookingType.GROUP)throw new ApiException(ErrorCode.PAYMENT_INVALID);}list=d.getReservationId()!=null?orders.findByReservationId(d.getReservationId()):orders.findByDiniTicketId(d.getDiniTicketId());}
 default->throw new ApiException(ErrorCode.PAYMENT_INVALID);}
 return list.stream().sorted(Comparator.comparing(FoodOrder::getId)).toList();}
 public BigDecimal claimed(UUID order){return jdbc.queryForObject("select coalesce(sum(l.amount),0) from payment_lines l join payments p on p.id=l.payment_id where l.food_order_id=? and p.status<>'FAILED'",BigDecimal.class,order);}
 public Payment cancelOffline(UUID actor,UUID id,PaymentRequests.Action q){var p=lock(id);if(!p.getCustomerId().equals(access.customer(actor)))throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);access.version(p.getVersion(),q.version());if(p.getGateway()!=PaymentGateway.CASH||p.getStatus()!=PaymentStatus.PENDING)throw new ApiException(ErrorCode.PAYMENT_INVALID);p.setStatus(PaymentStatus.FAILED);p.setFailureReason("Customer cancelled unconfirmed cash intent");payments.flush();audit.record(actor,"PAYMENT_CANCELLED","Payment",id,null);return p;}
 public boolean beginDispatch(UUID id){var p=lock(id);requireGatewayContext(p);if(p.getStatus()!=PaymentStatus.CREATED||p.getDispatchStartedAt()!=null||p.getGateway()!=PaymentGateway.RAZORPAY)return false;p.setDispatchStartedAt(clock.instant());payments.flush();return true;}
 public void attachOrder(UUID id,GatewayPort.GatewayOrder order){var p=lock(id);requireGatewayContext(p);if(!order.receipt().equals(id.toString())||order.amount()!=PaymentRules.minor(p.getAmount())||!order.currency().equals(p.getCurrency())||!com.bookeat.payment.gateway.RazorpayPaymentsGateway.validId(order.id()))throw new ApiException(ErrorCode.PAYMENT_INVALID);if(p.getGatewayOrderId()!=null&&!p.getGatewayOrderId().equals(order.id()))throw new ApiException(ErrorCode.PAYMENT_INVALID);p.setGatewayOrderId(order.id());if(p.getStatus()==PaymentStatus.CREATED)p.setStatus(PaymentStatus.PENDING);p.setFailureReason(null);payments.flush();}
 public void uncertain(UUID id){var p=lock(id);p.setFailureReason("Provider outcome requires reconciliation");payments.flush();}
 public void capture(UUID id,GatewayPort.GatewayPayment proof,UUID actor){var p=lock(id);requireGatewayContext(p);if(p.getGateway()!=PaymentGateway.RAZORPAY||!Objects.equals(p.getGatewayOrderId(),proof.orderId())||proof.amount()!=PaymentRules.minor(p.getAmount())||!p.getCurrency().equals(proof.currency())||proof.tax()<0||proof.fee()<proof.tax())throw new ApiException(ErrorCode.PAYMENT_INVALID);if(p.getStatus()==PaymentStatus.SUCCESS||p.getStatus()==PaymentStatus.PARTIALLY_REFUNDED||p.getStatus()==PaymentStatus.REFUNDED){if(!Objects.equals(p.getGatewayPaymentId(),proof.id()))throw new ApiException(ErrorCode.PAYMENT_INVALID);return;}if(p.getStatus()!=PaymentStatus.PENDING||!"captured".equals(proof.status())||proof.refunded()!=0)throw new ApiException(ErrorCode.PAYMENT_INVALID);success(p,actor,proof.id(),proof.method(),PaymentRules.major(proof.fee()-proof.tax()),PaymentRules.major(proof.tax()));}
 public void gatewayFailure(GatewayPort.GatewayPayment proof){var found=payments.findByGatewayOrderId(proof.orderId());if(found.isEmpty())return;var p=lock(found.get().getId());requireGatewayContext(p);if(p.getStatus()==PaymentStatus.PENDING&&"failed".equals(proof.status())){p.setFailureReason("Razorpay payment attempt failed: "+proof.id());payments.flush();}}
 public Payment cash(UUID actor,UUID rid,UUID id,PaymentRequests.Action q){access.lockOwner(actor,rid);var p=payments.findById(id).filter(x->x.getRestaurantId().equals(rid)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.version(p.getVersion(),q.version());if(p.getGateway()!=PaymentGateway.CASH)throw new ApiException(ErrorCode.PAYMENT_INVALID);if(p.getStatus()==PaymentStatus.SUCCESS)return p;if(p.getStatus()!=PaymentStatus.PENDING)throw new ApiException(ErrorCode.PAYMENT_INVALID);success(p,actor,null,"CASH",BigDecimal.ZERO,BigDecimal.ZERO);return p;}
 private void success(Payment p,UUID actor,String gatewayPayment,String method,BigDecimal fee,BigDecimal tax){p.setStatus(PaymentStatus.SUCCESS);p.setVerifiedAt(clock.instant());p.setGatewayPaymentId(gatewayPayment);p.setPaymentMethod(method);p.setGatewayFee(fee);p.setGatewayTax(tax);payments.flush();for(var l:lines.findByPaymentId(p.getId())){var o=orders.findById(l.getFoodOrderId()).orElseThrow();if(o.getTakeawayOrderId()!=null){var t=takeaways.findById(o.getTakeawayOrderId()).orElseThrow();t.setPaymentStatus(paid(o.getId(),o.getTotal())?OrderPaymentStatus.PAID:OrderPaymentStatus.PARTIALLY_PAID);}if(o.getReservationId()!=null){var r=reservations.findById(o.getReservationId()).orElseThrow();r.setPaymentStatus(orders.findByReservationId(r.getId()).stream().filter(x->x.getStatus()!=FoodOrderStatus.CANCELLED&&x.getStatus()!=FoodOrderStatus.REJECTED).allMatch(x->paid(x.getId(),x.getTotal()))?BookingPaymentStatus.PAID:BookingPaymentStatus.PARTIALLY_PAID);}}audit.record(actor,"PAYMENT_SUCCESS","Payment",p.getId(),null);payments.flush();}
 public boolean paid(UUID order,BigDecimal amount){BigDecimal paid=jdbc.queryForObject("select coalesce(sum(l.amount),0) from payment_lines l join payments p on p.id=l.payment_id where l.food_order_id=? and p.status in ('SUCCESS','PARTIALLY_REFUNDED','REFUNDED')",BigDecimal.class,order);return paid.compareTo(amount)>=0;}
 public Payment lock(UUID id){access.lock(payments.restaurantId(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND)));return payments.findById(id).orElseThrow();}
 public void requireGatewayContext(Payment p){if(p.getGateway()!=PaymentGateway.RAZORPAY||!gateway.enabled()||!Objects.equals(p.getGatewayAccountId(),gateway.accountId())||p.getGatewaySandbox()==null||p.getGatewaySandbox()!=gateway.sandbox())throw new ApiException(ErrorCode.PAYMENT_GATEWAY_UNAVAILABLE);}
}
